  'about.title': 'Sport brings people together.',
  'about.subtitle': 'Jynlo brings people together through sport. Discover games, find players, join communities and keep up with your games in one place.',
  'about.who.title': 'Who we are',
  'about.who.text': 'We are a platform for people who want to play sport, meet other players and turn plans into real games.',
  'about.goal.title': 'Our goal',
  'about.goal.text': 'Make sports activities easier to discover and organise, from a casual game to a thriving community.',
  'about.more.title': 'More than games',
  'about.more.text': 'Every game can be the start of a team, competition, routine or new friendship.',
  'about.eyebrow': 'JYNLO AT A GLANCE',
  'about.explore': 'Explore activities',
  'about.features.eyebrow': 'WHAT YOU CAN DO',
  'about.features.title': 'More than arranging a game.',
  'about.features.subtitle': 'From your first game to community championships, Jynlo helps you organise, join and follow your sporting life.',
  'about.features.sessions.title': 'Games and games',
  'about.features.sessions.text': 'Discover games, confirm your attendance or create games to bring players together. Share invites and see who\'s joining.',
  'about.features.communities.title': 'Communities',
  'about.features.communities.text': 'Create or join groups of players, organise recurring games and stay connected around your favourite sport.',
  'about.features.competitions.title': 'Tournaments and championships',
  'about.features.competitions.text': 'Organise competitions, follow fixtures and results, and bring different events together in community-customised championships.',
  'about.features.stats.title': 'Results and rankings',
  'about.features.stats.text': 'Follow tables, statistics and performance when ranking mode is enabled in your community.',
  'about.features.venues.title': 'Sports venues',
  'about.features.venues.text': 'Find places to play, browse venue information and discover sporting locations near you.',
  'about.features.social.title': 'Feed and messages',
  'about.features.social.text': 'Share moments in the feed, follow updates and arrange upcoming games in community conversations.',
  'about.journey.eyebrow': 'GETTING STARTED IS EASY',
  'about.journey.title': 'From \'shall we play?\' to your next game.',
  'about.journey.discover.title': 'Discover',
  'about.journey.discover.text': 'Find a sport, venue, game or community.',
  'about.journey.play.title': 'Take part',
