  "Ainda sem modalidades definidas": "No sports set yet",
  "Ajuda-nos a perceber o problema. Até 8 ficheiros e 16 MB no total. Imagens até 3 MB; vídeos, áudio e PDF até 12 MB cada. Também podes colar capturas na mensagem.": "Help us understand the problem. Up to 8 files and 16 MB in total. Images up to 3 MB; videos, audio and PDF up to 12 MB each. You can also paste screenshots into the message.",
