  "Apuramento direto na primeira ronda:": "Straight through in the first round:",
  "Arrasta a fotografia ou o texto com o rato. As pegas ↻ e ↘ permitem rodar e redimensionar cada elemento.": "Drag the photo or the text with the mouse. The ↻ and ↘ handles rotate and resize each element.",
  "Arrasta o texto na fotografia. ↻ roda e ↘ ajusta o tamanho.": "Drag the text on the photo. ↻ rotates and ↘ resizes.",
  "Arrastar a fotografia para mover, usar as pegas para rodar ou redimensionar": "Drag the photo to move it, use the handles to rotate or resize",
  "As Ligas e Taças internas de Futebol e Futsal permitem registar resultados e vencedores. Cada prova interna concluída atribui 10 pontos ao vencedor na classificação geral da época; no modo independente, guarda apenas o respetivo título. Os restantes formatos terão regras próprias antes de serem ativados.": "The internal Football and Futsal Leagues and Cups let you record results and winners. Each finished internal event awards 10 points to the winner in the season's overall standings; in independent mode it only keeps the title. The other formats will get their own rules before they're turned on.",
  "As fotografias e os vídeos são mantidos.": "Photos and videos are kept.",
  "As ligas e taças internas disponíveis aqui funcionam com equipas e confrontos. Esta modalidade ainda não tem um motor de equipas compatível. Podes manter o campeonato e consultar provas existentes, mas não criar provas novas neste formato.": "The internal leagues and cups available here work with teams and matches. This sport doesn't have a compatible team engine yet. You can keep the championship and see existing events, but not create new events in this format.",
