  "A classificação deve usar as notas e o formato específico da prova. Usa os eventos disponíveis nas jornadas; não vamos converter notas em vitórias fictícias.": "The standings must use the event's scores and specific format. Use the events available in the rounds; we won't turn scores into made-up wins.",
  "A classificação utiliza os pontos por vitória, empate ou derrota. Os resultados e a classificação pertencem apenas ao torneio, sem alterar as estatísticas habituais da comunidade.": "The standings use points per win, draw or loss. Results and standings belong only to the tournament and don't change the community's usual stats.",
