  "Corridas individuais utilizam tempos; saltos e lançamentos utilizam marcas; as estafetas disponíveis utilizam equipas. Seleciona uma disciplina compatível antes de registar resultados.": "Individual races use times; jumps and throws use marks; the available relays use teams. Select a compatible discipline before recording results.",
