  "Escreve o título do direto.": "Write the live stream title.",
  "Escreve um nome de modalidade válido (2–60 caracteres), ou escolhe uma sugestão do catálogo.": "Write a valid sport name (2–60 characters), or choose a suggestion from the catalogue.",
  "Essa imagem já foi adicionada.": "That image has already been added.",
  "Esta ação não pode ser anulada. Se houver jogadores, convites, mensagens, competições ou histórico, o servidor não permitirá a eliminação.": "This can't be undone. If there are players, invitations, messages, competitions or history, the server won't allow the deletion.",
  "Esta liga regista o resultado numérico final de cada confronto. Ainda não suporta resultados detalhados por set, assalto ou outros formatos específicos das jornadas. Os pontos por vitória, empate e derrota são configuráveis.": "This league records the final numeric result of each match. It doesn't support detailed results per set, round or other round-specific formats yet. Points per win, draw and loss can be set.",
  "Esta mensagem pode ter sido eliminada. A verificar o histórico.": "This message may have been deleted. Checking the history.",
  "Esta modalidade não tem um formato oficial de competição individual definido neste ecrã. Podes continuar a criar jogos e jornadas.": "This sport doesn't have an official individual competition format defined on this screen. You can keep creating games and rounds.",
  "Esta publicação não está disponível ou não tens permissão para a ver.": "This post isn't available or you don't have permission to see it.",
  "Este jogo já não pode ser cancelado ou não és o organizador.": "This game can no longer be cancelled, or you aren't the organiser.",
  "Este campeonato já não existe. Atualiza a lista de campeonatos antes de tentares novamente.": "This championship no longer exists. Refresh the championship list before trying again.",
  "Este desafio foi alterado noutra jogo. Verifica o estado antes de repetir.": "This challenge was changed in another game. Check its status before repeating.",
  "Este direto já terminou ou não está disponível.": "This live stream has ended or isn't available.",
  "Este direto terminou ou já não está disponível.": "This live stream ended or is no longer available.",
  "Este ficheiro não foi aceite. Experimenta uma imagem JPG/PNG diferente.": "This file wasn't accepted. Try a different JPG/PNG image.",
  "Este navegador não suporta a criação de emblemas.": "This browser doesn't support creating crests.",
  "Estão disponíveis apenas os modelos de resultados já implementados. As regras detalhadas de cada federação e disciplina podem necessitar de suporte adicional.": "Only the results models already built are available. Each federation's and discipline's detailed rules may need extra support.",
  "Formato atual: apenas o total de sets ganhos por participante em cada confronto. Não regista o resultado de cada set nem organiza pares/equipas. As regras de vitória e desempate por modalidade ainda serão configuráveis.": "Current format: only the total sets won per participant in each match. It doesn't record each set's result or organise pairs/teams. Each sport's win and tie-break rules will become configurable.",
  "Formato atual: confrontos entre participantes individuais, com um marcador numérico por encontro. Ainda não suporta pares, equipas nem provas por tempos ou distâncias; os critérios de desempate são genéricos.": "Current format: matches between individual participants, with a numeric score per match. It doesn't support pairs, teams or events by times or distances yet; tie-break criteria are generic.",
  "Formato atual: confrontos entre participantes individuais, com um marcador numérico por encontro. Ainda não suporta pares, equipas nem provas por tempos ou distâncias; os critérios de desempate são genéricos. Confirma se o marcador numérico faz sentido para a tua modalidade antes de organizar uma liga.": "Current format: matches between individual participants, with a numeric score per match. It doesn't support pairs, teams or events by times or distances yet; tie-break criteria are generic. Check whether a numeric score makes sense for your sport before organising a league.",
  "Formato não suportado. Usa JPG, PNG, WebP, MP4 ou WebM.": "Unsupported format. Use JPG, PNG, WebP, MP4 or WebM.",
  "Formato não suportado. Usa imagem, PDF ou áudio WebM/Ogg.": "Unsupported format. Use an image, PDF or WebM/Ogg audio.",
  "Formato por definir": "Format to be defined",
  "Golfe, bowling e outras modalidades por marca têm regras diferentes entre si. As provas já suportadas nas jornadas devem continuar a utilizar o seu formato próprio.": "Golf, bowling and other mark-based sports have different rules from each other. Events already supported in the rounds should keep using their own format.",
