  "Nesta modalidade, a classificação depende das posições, tempos e ocorrências da prova. Estas informações já são tratadas nas jornadas da comunidade. O formato atual de liga individual cria confrontos 1 vs 1, por isso não pode produzir uma classificação de corrida válida.": "In this sport, the standings depend on the event's positions, times and incidents. This is already handled in the community's rounds. The current individual league format creates 1 vs 1 matches, so it can't produce valid race standings.",
