  "O kata depende de avaliação técnica e o kumite de combates por categorias. Podes organizar a época, mas não existe ainda um motor automático específico para estas provas. Não serão tratadas como futebol.": "Kata depends on technical judging and kumite on bouts by category. You can organise the season, but there's no specific automatic engine for these events yet. They won't be treated as football.",
  "O motor atual suporta apenas as disciplinas individuais de piscina de 50 m explicitamente disponíveis na criação. Estafetas e outras distâncias não devem receber classificações automáticas sem suporte próprio.": "The current engine only supports the individual 50 m pool events explicitly available when creating. Relays and other distances shouldn't get automatic standings without their own support.",
