  "Os vossos campos com mais jogadores, sem custos.": "More players on your courts, at no cost.",
  "A Jynlo junta quem quer jogar. Ponham os vossos horários na Jynlo e recebam pedidos de reserva de jogadores da vossa zona, num painel simples.": "Jynlo brings together people who want to play. Put your times on Jynlo and get booking requests from players nearby, in a simple dashboard.",
  "Encontrar o meu recinto": "Find my venue",
  "Falar connosco": "Talk to us",
  "A página de reservas e o painel do recinto na Jynlo, com dados de exemplo": "The booking page and the venue dashboard on Jynlo, with sample data",
  "Imagens com dados de exemplo.": "Images with sample data.",
  "O que ganham": "What you get",
  "Reservas sem custos": "Bookings at no cost",
  "Os jogadores veem os vossos horários livres e pedem a reserva na app ou no site. Sem mensalidades nem comissões para os primeiros recintos parceiros.": "Players see your free times and request a booking in the app or on the website. No monthly fee and no commission for the first partner venues.",
  "Vocês decidem": "You decide",
  "Cada pedido chega ao vosso painel e só fica marcado quando o confirmam. Indicam os campos, os preços e o horário de funcionamento.": "Every request reaches your dashboard and is only booked once you confirm it. You set the courts, prices and opening hours.",
  "O dinheiro vai direto para vós": "The money goes straight to you",
  "Recebem por MB WAY no número do clube ou no local. A Jynlo não fica com nada.": "You get paid by MB WAY to the club's number or at the venue. Jynlo keeps nothing.",
  "Mais gente a jogar": "More people playing",
  "Cada reserva pode virar um jogo com convites a outros jogadores. Também podem criar comunidades, torneios e campeonatos.": "Each booking can become a game with invitations to other players. You can also create communities, tournaments and leagues.",
  "Como funciona": "How it works",
  "Do horário à reserva paga, em 5 passos": "From opening hours to a paid booking, in 5 steps",
