  "Indicam os campos e os preços": "Set your courts and prices",
  "Nome, modalidade, preço e duração de cada reserva. Podem desligar um campo quando quiserem.": "Name, sport, price and booking length for each court. You can switch a court off whenever you like.",
  "Definem o horário de funcionamento": "Set your opening hours",
  "Um ou mais períodos por dia. Os horários livres são criados a partir daqui, sem mais trabalho.": "One or more periods a day. Free times are created from this, with no extra work.",
  "O jogador escolhe um horário livre": "The player picks a free time",
  "Vê só os horários livres, com o preço, e pede a reserva. Pode também criar logo o jogo e convidar outros jogadores.": "They only see free times, with the price, and request the booking. They can also create the game right away and invite other players.",
  "Vocês confirmam ou recusam": "You confirm or decline",
  "Cada pedido chega com o dia, a hora, o campo e a mensagem do jogador. Nada fica marcado sem a vossa confirmação.": "Each request comes with the day, time, court and the player's message. Nothing is booked without your confirmation.",
  "O jogador paga e vocês confirmam": "The player pays and you confirm",
  "Depois de confirmada, o jogador vê o vosso número de MB WAY e marca que pagou. Vocês carregam em “Pagamento recebido”.": "Once confirmed, the player sees your MB WAY number and marks it as paid. You tap “Payment received”.",
