  "Indiquem os campos, os preços e o horário.": "Set the courts, prices and opening hours.",
  "Os horários livres passam a aparecer aos jogadores e os pedidos chegam ao vosso painel.": "Free times start showing to players and requests reach your dashboard.",
  "Perguntas frequentes": "Frequently asked questions",
  "Tem algum custo?": "Does it cost anything?",
  "Não. Para os primeiros recintos parceiros não há mensalidade nem comissão sobre as reservas.": "No. For the first partner venues there is no monthly fee and no commission on bookings.",
  "Já usamos outra plataforma de reservas. Podemos usar as duas?": "We already use another booking platform. Can we use both?",
  "Sim. Podem pôr na Jynlo só alguns campos ou horários, e recusar qualquer pedido que não dê jeito.": "Yes. You can put only some courts or times on Jynlo, and decline any request that doesn't suit you.",
  "Como recebemos os pagamentos?": "How do we get paid?",
  "Por MB WAY no número que indicarem, ou no local. O jogador marca que pagou e vocês confirmam no painel.": "By MB WAY to the number you give, or at the venue. The player marks it as paid and you confirm in the dashboard.",
  "Podemos organizar torneios?": "Can we run tournaments?",
  "Sim. Criem uma comunidade do clube e organizem torneios e campeonatos, com inscrições pagas por MB WAY.": "Yes. Create a club community and run tournaments and leagues, with entry fees paid by MB WAY.",
  "Preferem falar primeiro?": "Would you rather talk first?",
  "Escrevam-nos e ajudamos a configurar tudo. Demora uns 10 minutos.": "Write to us and we'll help set everything up. It takes about 10 minutes.",
  "Tens um recinto?": "Do you run a venue?",
  "Recebe reservas de jogadores da tua zona, sem custos. Tu confirmas e recebes por MB WAY ou no local.": "Get bookings from players nearby, at no cost. You confirm and get paid by MB WAY or at the venue.",
  "Saber mais": "Learn more",
  "Recebemos também o teu pedido para gerir o recinto. Quando for aprovado, avisamos-te e podes configurar os campos, os preços e o horário.": "We also got your request to manage the venue. Once it's approved, we'll let you know and you can set up the courts, prices and hours.",
  "Quero geri-lo na Jynlo e receber reservas, sem custos. Analisamos o recinto e o pedido ao mesmo tempo.": "I want to manage it on Jynlo and take bookings, at no cost. We review the venue and the request together.",
  "A tua função no recinto": "Your role at the venue",
  "Ex.: dono, gerente, direção do clube": "E.g. owner, manager, club board",
  "Diz-nos qual é a tua função no recinto.": "Tell us your role at the venue.",
  "Encontrem o vosso recinto na Jynlo, ou criem-no.": "Find your venue on Jynlo, or create it.",
  "Já temos mais de 4000 recintos no diretório. Se o vosso não estiver, criem-no em poucos minutos ou peçam-nos para o criar, nós tratamos disso.": "We already have more than 4000 venues in the directory. If yours isn't there, create it in a few minutes or ask us to create it, we'll take care of it.",
  "Pedir para criarem o nosso recinto": "Ask Jynlo to create our venue",
  "Digam-nos que são os responsáveis.": "Tell us you run it.",
  "Na página do recinto, ou ao criá-lo, marquem “Sou o responsável por este recinto”. Precisam de uma conta Jynlo, que é grátis. Confirmamos e ficam a gerir o recinto.": "On the venue's page, or when creating it, tick “I run this venue”. You need a Jynlo account, which is free. We confirm it and you manage the venue.",
  "Criar o meu recinto": "Create my venue",
  "Pede para gerir o recinto": "Asks to manage the venue",
  "Aprovar também o torna gestor.": "Approving also makes them its manager.",
