  "Personalizar a barra": "Customise the bar",
  "Escolhe o que aparece na barra, entre o Feed e o Criar. No telemóvel cabem as duas primeiras; o resto fica no menu da tua conta.": "Choose what shows in the bar, between Feed and Create. On a phone the first two fit; the rest stay in your account menu.",
