  "Como queres receber as reservas? A Jynlo não cobra nada e não recebe nem guarda dinheiro.": "How do you want to be paid for bookings? Jynlo charges nothing and never receives or holds money.",
  "Automático": "Automatic",
  "O jogador paga na app por MB WAY ou cartão e a reserva fica paga sozinha. O dinheiro vai direto para a conta Stripe do recinto. A Stripe desconta a comissão dela (cerca de 1,5% + 0,25 € por pagamento); a Jynlo não cobra nada.": "The player pays in the app by MB WAY or card and the booking is marked paid on its own. The money goes straight to the venue's Stripe account. Stripe takes its own fee (about 1.5% + €0.25 per payment); Jynlo charges nothing.",
  "A conta Stripe do recinto está ativa.": "The venue's Stripe account is active.",
  "Só quem gere o recinto pode ligar a conta Stripe da empresa.": "Only the venue's manager can connect the company's Stripe account.",
  "Falta acabar o registo na Stripe.": "The Stripe sign-up is not finished yet.",
  "Primeiro liga a conta Stripe do recinto. Os dados da empresa e o IBAN ficam na Stripe, não na Jynlo.": "First connect the venue's Stripe account. The company's details and IBAN stay with Stripe, not Jynlo.",
